func TestOriginalPortableChaChaTraces(t *testing.T) {
	for ix, row := range chachaOriginalTraces {
		t.Run(fmt.Sprint(ix), func(t *testing.T) {
			key := make([]byte, 32)
			nonce := make([]byte, row.NonceLen)
			for i := range key {
				key[i] = byte(i)
			}
			for i := range nonce {
				nonce[i] = byte(i)
			}
			c, e := JpuCElV(key, nonce)
			if e != nil {
				t.Fatal(e)
			}
			if unsafe.Sizeof(*c) != 144 {
				t.Fatal("RTTI")
			}
			if e = c.Seek(row.Seek); e != nil {
				t.Fatal(e)
			}
			state := func() string { return hex.EncodeToString(unsafe.Slice((*byte)(unsafe.Pointer(c)), 144)) }
			if state() != row.Initial {
				t.Fatal("initial state")
			}
			for _, v := range row.Effects {
				input, _ := hex.DecodeString(v.Input)
				out := make([]byte, len(input))
				for i := range out {
					out[i] = 0xee
				}
				panicked := false
				func() {
					defer func() {
						if recover() != nil {
							panicked = true
						}
					}()
					c.XORKeyStream(out[:len(out)-row.Short], input)
				}()
				if (v.Outcome == "panic") != panicked {
					t.Fatalf("panic=%v want%s", panicked, v.Outcome)
				}
				if hex.EncodeToString(out) != v.Output {
					t.Fatal("output mismatch")
				}
				if state() != v.State {
					t.Fatal("post-call state mismatch")
				}
			}
		})
	}
}
